package com.example.ancapp.ui

import android.app.Application
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import com.example.ancapp.data.AncRepository
import com.example.ancapp.data.PatientItem
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

class RegisterViewModel(app: Application) : AndroidViewModel(app) {
  private val repository = AncRepository(app)

  private val _patients = MutableStateFlow<List<PatientItem>>(emptyList())
  val patients = _patients.asStateFlow()

  private val _isLoading = MutableStateFlow(false)
  val isLoading = _isLoading.asStateFlow()

  fun loadPatients() {
    viewModelScope.launch {
      _isLoading.value = true
      try {
        _patients.value = repository.getPatients()
      } catch (e: Exception) {
        e.printStackTrace()
      } finally {
        _isLoading.value = false
      }
    }
  }
}

package com.example.ancapp.ui

import android.app.Application
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import com.example.ancapp.data.AncRepository
import com.example.ancapp.data.PastVisitItem
import com.example.ancapp.data.PatientItem
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

class PatientDetailViewModel(app: Application) : AndroidViewModel(app) {
  private val repository = AncRepository(app)

  private val _patient = MutableStateFlow<PatientItem?>(null)
  val patient = _patient.asStateFlow()

  private val _visits = MutableStateFlow<List<PastVisitItem>>(emptyList())
  val visits = _visits.asStateFlow()

  private val _isLoading = MutableStateFlow(false)
  val isLoading = _isLoading.asStateFlow()

  fun loadDetails(patientId: String) {
    viewModelScope.launch {
      _isLoading.value = true
      try {
        val (p, v) = repository.getPatientDetails(patientId)
        _patient.value = p
        _visits.value = v
      } catch (e: Exception) {
        e.printStackTrace()
      } finally {
        _isLoading.value = false
      }
    }
  }
}

package com.example.ancapp.ui

import android.app.Application
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import com.example.ancapp.data.AncRepository
import dev.ohs.fhir.model.r4.QuestionnaireResponse
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

class RecordVisitViewModel(app: Application) : AndroidViewModel(app) {
  private val repository = AncRepository(app)

  private val _questionnaireJson = MutableStateFlow<String?>(null)
  val questionnaireJson = _questionnaireJson.asStateFlow()

  fun loadQuestionnaire() {
    viewModelScope.launch {
      try {
        _questionnaireJson.value = repository.getQuestionnaireJson()
      } catch (e: Exception) {
        _questionnaireJson.value = AncRepository.BUNDLED_ANC_QUESTIONNAIRE_JSON
      }
    }
  }

  suspend fun saveVisit(patientId: String, response: QuestionnaireResponse) {
    repository.saveNewVisit(patientId, response)
  }
}

