@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RegisterScreen(
  viewModel: RegisterViewModel,
  syncViewModel: SyncViewModel,
  onPatientClick: (String) -> Unit,
) {
  val patients by viewModel.patients.collectAsState()
  val isLoading by viewModel.isLoading.collectAsState()
  val syncState by syncViewModel.syncState.collectAsState()
  val isSyncing by syncViewModel.isSyncing.collectAsState()

  LaunchedEffect(Unit) {
    viewModel.loadPatients()
    syncViewModel.syncNow {
      viewModel.loadPatients()
    }
  }

  Scaffold(
    topBar = {
      TopAppBar(
        title = {
          Column {
            Text(
              "Antenatal Care Register",
              style = MaterialTheme.typography.titleLarge,
              fontWeight = FontWeight.Bold,
            )
            syncState?.let { state ->
              Text(
                state,
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onPrimaryContainer.copy(alpha = 0.8f),
              )
            }
          }
        },
        actions = {
          IconButton(
            onClick = {
              syncViewModel.syncNow {
                viewModel.loadPatients()
              }
            },
            enabled = !isSyncing,
          ) {
            if (isSyncing) {
              CircularProgressIndicator(
                modifier = Modifier.size(24.dp),
                strokeWidth = 2.dp,
                color = MaterialTheme.colorScheme.onPrimaryContainer,
              )
            } else {
              Icon(Icons.Filled.Refresh, contentDescription = "Sync with server")
            }
          }
        },
        colors = TopAppBarDefaults.topAppBarColors(
          containerColor = MaterialTheme.colorScheme.primaryContainer,
          titleContentColor = MaterialTheme.colorScheme.onPrimaryContainer,
        ),
      )
    }
  ) { innerPadding ->
    Box(
      modifier = Modifier
        .fillMaxSize()
        .padding(innerPadding)
    ) {
      if (isLoading && patients.isEmpty()) {
        CircularProgressIndicator(modifier = Modifier.align(Alignment.Center))
      } else if (patients.isEmpty()) {
        Column(
          modifier = Modifier
            .align(Alignment.Center)
            .padding(24.dp),
          horizontalAlignment = Alignment.CenterHorizontally,
        ) {
          Text(
            "No currently pregnant patients found.",
            style = MaterialTheme.typography.bodyLarge,
          )
          Spacer(modifier = Modifier.height(12.dp))
          Text(
            "Tap the sync button above to fetch clinic data.",
            style = MaterialTheme.typography.bodyMedium,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
          )
        }
      } else {
        LazyColumn(
          modifier = Modifier.fillMaxSize(),
          contentPadding = PaddingValues(16.dp),
          verticalArrangement = Arrangement.spacedBy(12.dp),
        ) {
          items(patients, key = { it.id }) { patient ->
            PatientRegisterCard(
              patient = patient,
              onClick = { onPatientClick(patient.id) },
            )
          }
        }
      }
    }
  }
}

@Composable
fun PatientRegisterCard(
  patient: PatientItem,
  onClick: () -> Unit,
) {
  Card(
    modifier = Modifier
      .fillMaxWidth()
      .clickable(onClick = onClick),
    shape = RoundedCornerShape(12.dp),
    elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
    colors = CardDefaults.cardColors(
      containerColor = MaterialTheme.colorScheme.surface,
    ),
  ) {
    Row(
      modifier = Modifier
        .fillMaxWidth()
        .padding(16.dp),
      verticalAlignment = Alignment.CenterVertically,
    ) {
      Column(modifier = Modifier.weight(1f)) {
        Row(
          verticalAlignment = Alignment.CenterVertically,
          horizontalArrangement = Arrangement.SpaceBetween,
          modifier = Modifier.fillMaxWidth()
        ) {
          Text(
            text = patient.name,
            style = MaterialTheme.typography.titleMedium,
            fontWeight = FontWeight.Bold,
          )
          Surface(
            shape = RoundedCornerShape(16.dp),
            color = MaterialTheme.colorScheme.secondaryContainer,
          ) {
            Text(
              text = patient.currentWeeksDisplay,
              style = MaterialTheme.typography.labelMedium,
              fontWeight = FontWeight.SemiBold,
              color = MaterialTheme.colorScheme.onSecondaryContainer,
              modifier = Modifier.padding(horizontal = 10.dp, vertical = 4.dp),
            )
          }
        }

        Spacer(modifier = Modifier.height(8.dp))

        Row(
          modifier = Modifier.fillMaxWidth(),
          horizontalArrangement = Arrangement.spacedBy(16.dp),
        ) {
          Row(verticalAlignment = Alignment.CenterVertically) {
            Icon(
              Icons.Filled.PregnantWoman,
              contentDescription = null,
              modifier = Modifier.size(16.dp),
              tint = MaterialTheme.colorScheme.onSurfaceVariant,
            )
            Spacer(modifier = Modifier.width(4.dp))
            Text(
              text = "Age: ${patient.age?.let { "$it yrs" } ?: "N/A"}",
              style = MaterialTheme.typography.bodyMedium,
              color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
          }

          Row(verticalAlignment = Alignment.CenterVertically) {
            Icon(
              Icons.Filled.CalendarToday,
              contentDescription = null,
              modifier = Modifier.size(16.dp),
              tint = MaterialTheme.colorScheme.onSurfaceVariant,
            )
            Spacer(modifier = Modifier.width(4.dp))
            Text(
              text = "Due: ${patient.eddDisplay}",
              style = MaterialTheme.typography.bodyMedium,
              fontWeight = FontWeight.Medium,
              color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
          }
        }
      }

      Spacer(modifier = Modifier.width(8.dp))

      Icon(
        Icons.AutoMirrored.Filled.ArrowForward,
        contentDescription = "View patient details",
        tint = MaterialTheme.colorScheme.primary,
      )
    }
  }
}

