@Composable
fun PatientDetailScreen(
  patientId: String,
  viewModel: PatientDetailViewModel,
  onBack: () -> Unit,
  onRecordVisitClick: (String) -> Unit,
) {
  val patient by viewModel.patient.collectAsState()
  val visits by viewModel.visits.collectAsState()
  val isLoading by viewModel.isLoading.collectAsState()

  LaunchedEffect(patientId) {
    viewModel.loadDetails(patientId)
  }

  Scaffold(
    topBar = {
      TopAppBar(
        title = { Text(patient?.name ?: "Patient Details") },
        navigationIcon = {
          IconButton(onClick = onBack) {
            Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back")
          }
        },
        colors = TopAppBarDefaults.topAppBarColors(
          containerColor = MaterialTheme.colorScheme.primaryContainer,
          titleContentColor = MaterialTheme.colorScheme.onPrimaryContainer,
        ),
      )
    },
    floatingActionButton = {
      ExtendedFloatingActionButton(
        onClick = { onRecordVisitClick(patientId) },
        icon = { Icon(Icons.Filled.Add, contentDescription = null) },
        text = { Text("Record ANC Visit") },
        containerColor = MaterialTheme.colorScheme.primary,
        contentColor = MaterialTheme.colorScheme.onPrimary,
      )
    }
  ) { innerPadding ->
    Box(
      modifier = Modifier
        .fillMaxSize()
        .padding(innerPadding)
    ) {
      if (isLoading && patient == null) {
        CircularProgressIndicator(modifier = Modifier.align(Alignment.Center))
      } else {
        LazyColumn(
          modifier = Modifier.fillMaxSize(),
          contentPadding = PaddingValues(16.dp),
          verticalArrangement = Arrangement.spacedBy(16.dp),
        ) {
          patient?.let { p ->
            item {
              PatientHeaderCard(patient = p)
            }
          }

          item {
            Row(
              modifier = Modifier.fillMaxWidth(),
              horizontalArrangement = Arrangement.SpaceBetween,
              verticalAlignment = Alignment.CenterVertically,
            ) {
              Text(
                text = "Past ANC Visits",
                style = MaterialTheme.typography.titleMedium,
                fontWeight = FontWeight.Bold,
              )
              Text(
                text = "${visits.size} recorded",
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
              )
            }
          }

          if (visits.isEmpty()) {
            item {
              Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(
                  containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f),
                )
              ) {
                Box(
                  modifier = Modifier
                    .fillMaxWidth()
                    .padding(32.dp),
                  contentAlignment = Alignment.Center,
                ) {
                  Text(
                    text = "No past visits recorded yet.",
                    style = MaterialTheme.typography.bodyMedium,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                  )
                }
              }
            }
          } else {
            items(visits, key = { it.encounterId }) { visit ->
              PastVisitCard(visit = visit)
            }
          }

          // Spacer so the last card isn't obscured by the FAB
          item {
            Spacer(modifier = Modifier.height(64.dp))
          }
        }
      }
    }
  }
}

